// Package airbnb is the hand-built client for Airbnb's internal persisted-query
// GraphQL API (/api/v3) plus the legacy REST surface (/api/v2). It is not
// generated by the Printing Press: Airbnb ships no public API, so the transport,
// auth, operation registry and typed methods are authored from traffic captured
// against a logged-in browser session.
package airbnb

import (
	"encoding/base64"
	"strings"
)

// Airbnb encodes most GraphQL node IDs as base64 of "Type:numericId", e.g.
// "MessageThread:980001234567" -> "TWVzc2FnZVRocmVhZDo5ODAwMDEyMzQ1Njc=". These
// helpers convert between the numeric ID a user passes on the command line and
// the encoded global ID the API expects. Airbnb uses URL-safe base64 without
// padding in some contexts and standard base64 in others, so decoding tries
// both.

// EncodeGlobalID returns base64("<typ>:<id>").
func EncodeGlobalID(typ, id string) string {
	return base64.StdEncoding.EncodeToString([]byte(typ + ":" + id))
}

// DecodeGlobalID decodes a base64 global ID into its type and numeric parts.
// Returns ok=false when the input is not a decodable "Type:id" global ID.
func DecodeGlobalID(encoded string) (typ, id string, ok bool) {
	for _, dec := range []*base64.Encoding{
		base64.StdEncoding, base64.RawStdEncoding,
		base64.URLEncoding, base64.RawURLEncoding,
	} {
		raw, err := dec.DecodeString(encoded)
		if err != nil {
			continue
		}
		s := string(raw)
		if i := strings.IndexByte(s, ':'); i > 0 {
			return s[:i], s[i+1:], true
		}
	}
	return "", "", false
}

// NormalizeThreadID accepts either a numeric thread ID or an already-encoded
// global ID and returns the base64 MessageThread global ID the messaging API
// expects.
func NormalizeThreadID(input string) string {
	if _, _, ok := DecodeGlobalID(input); ok {
		return input
	}
	return EncodeGlobalID("MessageThread", input)
}

// NormalizeViewerID returns the base64 Viewer global ID for a numeric user ID,
// accepting an already-encoded value unchanged.
func NormalizeViewerID(input string) string {
	if _, _, ok := DecodeGlobalID(input); ok {
		return input
	}
	return EncodeGlobalID("Viewer", input)
}

// NumericID returns the numeric portion of an ID that may be either a raw
// numeric string or an encoded "Type:id" global ID.
func NumericID(input string) string {
	if _, id, ok := DecodeGlobalID(input); ok {
		return id
	}
	return input
}

// StayListingGlobalID encodes a numeric listing ID as the DemandStayListing
// global ID used across search results and the PDP.
func StayListingGlobalID(listingID string) string {
	return EncodeGlobalID("DemandStayListing", NumericID(listingID))
}
